-- Dados ficticios para desenvolvimento e demonstracao local.
-- Execute depois que o Hibernate criar/atualizar as tabelas.
-- Script PostgreSQL, seguro para executar novamente: IDs fixos e conflitos ignorados,
-- exceto as contas, que atualizam a senha/role para garantir os logins locais.
-- NAO use estas contas nem estes dados em producao.

BEGIN;

-- Contas de demonstracao. Senhas codificadas com BCryptPasswordEncoder do projeto.
-- Credenciais em texto para uso local estao em arquivo.env.
ON CONFLICT (username) DO UPDATE SET
    password = EXCLUDED.password,
    role = EXCLUDED.role;

-- Funcionarios do negocio (o usuario de autenticacao e uma entidade separada).
ON CONFLICT (id) DO NOTHING;

